const BALANCE_STATE_KEY = 'ruhestandsmodellValues_v29_guardrails';
const EXPENSES_KEY = 'balance_expenses_v1';

function currentPersonBalanceFixture(raw) {
    try {
        const state = JSON.parse(raw);
        if (state?.inputs && typeof state.inputs === 'object') {
            const evidence = { ...(state.personInputEvidence || {}) };
            for (const key of ['aktuellesAlter', 'renteAktiv', 'renteMonatlich', 'sonstigeEinkuenfte', 'sparerPauschbetrag', 'kirchensteuerSatz']) {
                if (Object.hasOwn(state.inputs, key)) { evidence[key] = state.inputs[key]; delete state.inputs[key]; }
            }
            if (Object.keys(evidence).length) state.personInputEvidence = evidence;
        }
        return JSON.stringify(state);
    } catch { return raw; } // Gezielte beschädigte Fixtures bleiben beschädigt.
}

function createBalanceStorage(activeYear = 2025, planningYear = 2026) {
    const inputs = {
        aktuellesAlter: 67, floorBedarf: 12000, flexBedarf: 24000, minimumFlexAnnual: 0,
        flexBudgetAnnual: 7000, flexBudgetYears: 5, flexBudgetRecharge: 5000,
        inflation: 2, tagesgeld: 100000, geldmarktEtf: 0, depotwertAlt: 500000,
        depotwertNeu: 0, endeVJ: 100, endeVJ_1: 95, endeVJ_2: 90, endeVJ_3: 85,
        ath: 105, jahreSeitAth: 1, renteAktiv: false, renteMonatlich: 0,
        marketCapeRatio: 25, capeRatio: 25
    };
    return {
        [BALANCE_STATE_KEY]: currentPersonBalanceFixture(JSON.stringify({
            inputs,
            lastState: { cumulativeInflationFactor: 1, lastInflationAppliedAtAge: 67, taxState: { lossCarry: 0 } },
            annualPeriodMetadata: { schemaVersion: 1, lastCommittedPeriod: null, pendingCommit: null }
        })),
        profile_person_schema_version: '1',
        profile_geburtsdatum: `${planningYear - 68}-03-14`,
        profile_geschlecht: 'm',
        profile_rente_monatlich: '0',
        profile_tagesgeld: '100000',
        [EXPENSES_KEY]: JSON.stringify({ version: 1, activeYear, years: { [activeYear]: { months: {} } } })
    };
}

// Seit der gemeinsamen Planungsstartregel (Paket 12 Slice 1) bietet Balance den Jahresabschluss nur für ein
// belegtes Planungsjahr an; ohne Beleg erscheint der Erstjahrhinweis. Ein erfasster Ausgabenmonat im
// Abschlussjahr ist der kleinste echte Beleg und lässt Perioden-, Vermögens- und Personendaten unberührt.
// Ohne Registry legt die App das Einzelprofil „default“ an.
function withClosingYearExpenseEvidence(storage, closingYear, profileId = 'default') {
    const store = JSON.parse(storage[EXPENSES_KEY]);
    store.years[closingYear] = { months: { ...(store.years[closingYear]?.months || {}),
        6: { profiles: { [profileId]: { categories: { Ausgabe: -250 } } } } } };
    return { ...storage, [EXPENSES_KEY]: JSON.stringify(store) };
}

function createBrowserTranche(overrides = {}) {
    return {
        schemaVersion: 2,
        trancheId: 'browser-lot-1',
        name: 'Synthetische Browser-Tranche',
        isin: '',
        ticker: 'FLOW.DE',
        shares: 2,
        purchasePrice: 100,
        currentPrice: 90,
        purchaseDate: '2024-01-02',
        category: 'equity',
        type: 'aktien_neu',
        tqf: 0.3,
        taxExempt: false,
        notes: '',
        ...overrides
    };
}

function createBrowserProfileStorage(profiles, currentProfileId) {
    const registry = {
        version: 1,
        profiles: Object.fromEntries(Object.entries(profiles).map(([id, profile]) => [id, {
            meta: {
                id,
                name: profile.name,
                createdAt: '2026-07-14T00:00:00.000Z',
                updatedAt: '2026-07-14T00:00:00.000Z',
                belongsToHousehold: profile.belongsToHousehold !== false
            },
            data: {
                ...(profile.omitTranches === true
                    ? {}
                    : { depot_tranchen: profile.tranchesRaw ?? '[]' }),
                profile_tagesgeld: profile.tagesgeld ?? '10000',
                // Reihenfolge wie beim produktiven Profilspeichern: Geburtsdatum vor Schemaversion.
                ...(profile.missingPersonData ? {} : { profile_geburtsdatum: `${(profile.planningYear ?? 2026) - Number(profile.alter ?? 67) - 1}-03-14` }),
                profile_person_schema_version: '1',
                ...(profile.extraData || {}),
                ...(profile.healthBucketRaw !== undefined
                    ? { profile_health_bucket: profile.healthBucketRaw }
                    : {}),
                ...(profile.balanceStateRaw !== undefined
                    ? { [BALANCE_STATE_KEY]: currentPersonBalanceFixture(profile.balanceStateRaw) }
                    : {})
            }
        }]))
    };
    return {
        rs_profiles_v1: JSON.stringify(registry),
        rs_current_profile: currentProfileId,
        rs_active_profile: currentProfileId
    };
}

export function createOverviewFirstPlanningFixture() {
    const state = JSON.parse(createBalanceStorage(2026)[BALANCE_STATE_KEY]);
    delete state.annualPeriodMetadata;
    // Ein unmarkierter Erststart hat keinen Beleg einer früheren Inflationsanpassung.
    // Der generische Balance-State enthält lastInflationAppliedAtAge=67; ohne
    // Periodenmetadaten verlangt deriveAnnualCloseEvidence dafür ausdrücklich Klärung.
    delete state.lastState.lastInflationAppliedAtAge;
    state.wealthHistory = { schemaVersion: 1, entries: [createManualWealthHistoryEntry({
        tagesgeld: 100000, geldmarktEtf: 0, depotwertAlt: 0, depotwertNeu: 0
    }, '2026-01-01')] };
    return createBrowserProfileStorage({ 'january-person': { name: 'Synthetischer Rückblick',
        balanceStateRaw: JSON.stringify(state), tagesgeld: '100000', alter: '67' } }, 'january-person');
}

// H1 Slice 1: Fachfremde Fixtures starten mit dem Plandatensatz, den die stille Umstellung aus
// denselben Quellen schreiben würde. So prüfen sie ihre Seite ohne Startumstellung, ohne den
// Rückkehrpunkt „Vor Umstellung Haushalt & Plan“ und ohne verschobenes Seitenstart-Timing.
// Die Umstellung selbst prüfen ausschließlich die Fälle mit expectPlanMigration.
function withHouseholdPlanFixture(storage, fixedTime) {
    if (storage.household_plan_v1 != null) return storage;
    // Ohne Registry legt der Profilstart das Einzelprofil „default“ als Haushaltsmitglied an.
    const records = storage.rs_profiles_v1 ? storage : { ...storage, rs_active_profile: 'default',
        rs_profiles_v1: JSON.stringify({ version: 1, profiles: { default: { meta: { id: 'default', belongsToHousehold: true }, data: {} } } }) };
    try {
        const seeded = addDirectHouseholdPlans(records, { now: () => new Date(fixedTime || '2026-07-14T00:00:00.000Z') });
        return seeded.household_plan_v1 == null ? storage : { ...storage, household_plan_v1: seeded.household_plan_v1 };
    } catch { return storage; } // Beschädigte Registry-Fixtures behalten den Startpfad der App.
}

function assert(condition, message) {
    if (!condition) throw new Error(message);
}

// page.waitForFunction behandelt das Promise eines async-Prädikats sofort als erfüllt;
// asynchrone Seitenbedingungen werden deshalb über evaluate bis zum tatsächlichen Eintreten abgefragt.
async function waitForPageCondition(page, predicate, arg, { timeout = 30000, description = 'Seitenbedingung' } = {}) {
    const deadline = Date.now() + timeout;
    while (!await page.evaluate(predicate, arg)) {
        if (Date.now() > deadline) throw new Error(description + ' nicht rechtzeitig erfüllt');
        await new Promise(resolve => setTimeout(resolve, 100));
    }
}

// Designsystem-Schalter: Der Schieber liegt über der Checkbox; bedient wird wie vom Benutzer über das Label.
async function setDsToggle(page, id, checked) {
    const input = page.locator(`#${id}`);
    if (await input.isChecked() !== checked) await page.locator(`label:has(#${id})`).first().click();
    assert(await input.isChecked() === checked, `Schalter ${id} steht auf ${checked}`);
}

// Balance rendert die Haushaltsliste beim Start; sichtbar ist sie nur im Tab „Bedarf & Strategie“.
// H1: Ein neuer Planbereich (z. B. nach Haushaltsbeitritt im Test) wird beim nächsten Seitenstart
// umgestellt; Balance und Simulator laden ihre Eingaben erst danach. Wartet auf genau diesen Startauftrag.
async function waitForHouseholdPlanStart(page) {
    await waitForPageCondition(page, async () => {
        const { whenProfilePageReady } = await import('./app/profile/profile-navigation.js');
        await whenProfilePageReady(document);
        const { initializeHouseholdPlanPage } = await import('./app/profile/household-plan-dialog.js');
        return ['migrated', 'unchanged'].includes((await initializeHouseholdPlanPage({ doc: document, win: window })).status);
    });
}

