async function runBalanceAnnualPreflight(browser, baseUrl) {
    // Abschluss 2025 ist durch Ausgaben belegt. J+1 ist erlaubt; ein fremdes Jahr bleibt gesperrt.
    for (const activeYear of [2026, 2028]) {
        const smoke = await openSmokePage(browser, baseUrl, 'Balance.html', {
            storage: withClosingYearExpenseEvidence(createBalanceStorage(activeYear), 2025), annualFixtures: { targetYear: 2025 }
        });
        try {
            const { page } = smoke; await waitBalanceHouseholdList(page);
            const age = page.locator('#aktuellesAlter'); await age.waitFor({ state: 'attached' });
            const before = await age.inputValue();
            const expensesBefore = JSON.parse((await readIndexedDb(page, 'kv', 'balance_expenses_v1')).value);
            await page.locator('#jahresabschlussBtn').click();
            await prepareBrowserClose(page);
            await page.waitForFunction(() => { const button = document.getElementById('annualConfirmBtn'); return Boolean(button) && !button.disabled; });
            await prepareBrowserClose(page);
            await page.locator('#annualConfirmBtn').click();
            if (activeYear === 2028) {
                await page.locator('#balanceAnnualCloseMessage').filter({ hasText: 'Der Ausgabenstore passt nicht zur Jahresperiode.' }).waitFor();
                assert(await page.locator('.action-error-entry[data-scope="annual"]').count() === 0, 'Offener Jahresdialog erzeugt keinen verdeckten zweiten Jahresfehler');
                assert(await age.inputValue() === before, 'Fehlgeschlagener Preflight darf das Alter nicht mutieren');
                assert(await readIndexedDb(page, 'snapshots', null) === 0, 'Fremdes Ansichtsjahr erreicht keinen Snapshot');
                assert((await readIndexedDb(page, 'kv', 'balance_expenses_v1')).value === JSON.stringify(expensesBefore), 'Abgewiesener Start bewahrt Ausgabenbytes');
            } else {
                await waitForPageCondition(page, () => document.querySelector('#balanceAnnualClose')?.dataset.annualYearResult === 'confirmed');
                const state = await readBalanceBrowserState(page);
                assert(state.annualPeriodMetadata.lastCommittedPeriod === 'calendar-year:2025', 'Ansichtsjahr J+1 bestätigt genau Abschlussjahr J');
                const expenses = JSON.parse((await readIndexedDb(page, 'kv', 'balance_expenses_v1')).value);
                assert(expenses.activeYear === 2026 && JSON.stringify(expenses.years['2025']) === JSON.stringify(expensesBefore.years['2025']), 'Abschluss endet auf J+1 und bewahrt Vorjahresausgaben');
                assert(await readIndexedDb(page, 'snapshots', null) === 1, 'Gültiger Start erzeugt genau einen Jahressnapshot');
            }
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}

async function runBalancePreviewLifecycle(browser, baseUrl) {
    const seededStorage = createBalanceStorage(2025);
    const seededState = JSON.parse(seededStorage[BALANCE_STATE_KEY]);
    seededState.lastState = {
        ...seededState.lastState,
        taxState: { lossCarry: 20000 },
        flexBudget: { balanceYears: 3 },
        vpw: { streak: 4 },
        lastWithdrawal: 36000
    };
    seededStorage[BALANCE_STATE_KEY] = JSON.stringify(seededState);

    const smoke = await openSmokePage(browser, baseUrl, 'Balance.html', { storage: seededStorage });
    await waitBalanceHouseholdList(smoke.page);
    await smoke.page.locator('#floorBedarf').waitFor({ state: 'attached' });
    await smoke.page.waitForTimeout(750);

    const afterInitialRender = JSON.parse(
        (await readIndexedDb(smoke.page, 'kv', BALANCE_STATE_KEY)).value
    );
    assert(
        JSON.stringify(afterInitialRender.lastState) === JSON.stringify(seededState.lastState),
        'Initialrender darf den fachlichen Balance-State nicht fortschreiben'
    );

    await smoke.page.evaluate(async () => {
        const { getBalancePlanTrial, renderBalancePlanTrial } = await import('./app/balance/balance-plan-trial.js');
        getBalancePlanTrial().start(); renderBalancePlanTrial(document, { project: true });
    });
    await smoke.page.locator('#floorBedarf').evaluate(element => {
        element.value = '13000';
        for (let count = 0; count < 5; count++) {
            element.dispatchEvent(new Event('input', { bubbles: true }));
        }
    });
    await smoke.page.waitForTimeout(750);

    const afterRepeatedInputs = JSON.parse(
        (await readIndexedDb(smoke.page, 'kv', BALANCE_STATE_KEY)).value
    );
    // H1 Slice 2: Planfelder (Floor, Flex, Budgets …) speichert Balance nur noch im gemeinsamen Plan,
    // nicht mehr als Kopie in den Balance-Eingaben.
    const planScopeKey = planScope('household', ['default']).key;
    const planAfterInputs = JSON.parse((await readIndexedDb(smoke.page, 'kv', HOUSEHOLD_PLAN_KEY)).value);
    assert(planAfterInputs.entries[planScopeKey]?.values.floorBedarf === seededState.inputs.floorBedarf, 'Versuchseingaben ändern keinen bestätigten Plan');
    assert(!Object.hasOwn(afterRepeatedInputs.inputs, 'floorBedarf'), 'Balance-Eingaben tragen keine Planwertkopie mehr');
    assert(
        JSON.stringify(afterRepeatedInputs.lastState) === JSON.stringify(seededState.lastState),
        'Fuenf identische Eingaben duerfen Verlustvortrag, Flex, VPW und letzte Entnahme nicht fortschreiben'
    );
    // Erlaubt ist nur die haushaltsweite Resetevidenz der Planfelder (bisher lag sie in inputs).
    const lifecycle = afterRepeatedInputs.balanceStateLifecycle;
    assert(
        lifecycle === undefined || (Object.keys(lifecycle).join() === 'planInputEvidence'
            && lifecycle.planInputEvidence[planScopeKey]?.floorBedarf === seededState.inputs.floorBedarf),
        'Input-only Persistenz darf keinen Periodencommit vortaeuschen'
    );
    await smoke.page.evaluate(async () => {
        const { getBalancePlanTrial, renderBalancePlanTrial } = await import('./app/balance/balance-plan-trial.js');
        await getBalancePlanTrial().adopt(() => ['floorBedarf']); renderBalancePlanTrial(document, { project: true });
    });
    await smoke.page.reload({ waitUntil: 'load' });
    await waitBalanceHouseholdList(smoke.page);
    await smoke.page.waitForFunction(() => document.getElementById('floorBedarf')?.value === '13.000');
    smoke.assertNoErrors();
    await smoke.close();
}

async function runBalanceThreeBucketBear(browser, baseUrl) {
    const storage = createBalanceStorage(2025);
    const seededState = JSON.parse(storage[BALANCE_STATE_KEY]);
    seededState.inputs = {
        ...seededState.inputs,
        inflation: 0,
        liquidityRunwayYears: 1,
        endeVJ: 70,
        endeVJ_1: 100,
        endeVJ_2: 100,
        endeVJ_3: 100,
        ath: 100,
        jahreSeitAth: 1,
        decumulation: {
            mode: '3_bucket_jilge',
            bondTargetFactor: 5,
            drawdownTrigger: 15,
            bondRefillThreshold: 80
        }
    };
    storage[BALANCE_STATE_KEY] = JSON.stringify(seededState);

    const smoke = await openSmokePage(browser, baseUrl, 'Balance.html', { storage });
    const { page } = smoke;
    await waitBalanceHouseholdList(page);
    await page.waitForFunction(() => document.getElementById('entnahmeStrategie')?.value === '3_bucket_jilge');
    const diagnosis = await page.evaluate(async lastState => {
        const { UIReader } = await import('./app/balance/balance-reader.js');
        const inputs = UIReader.readAllInputs();
        const result = window.EngineAPI.simulateSingleYear({
            ...inputs,
            finalizeThreeBucketAction: true
        }, lastState);
        return {
            strategy: inputs.decumulation?.mode,
            realReturnEq: result.ui?.market?.realReturnEq,
            threeBucket: result.ui?.threeBucket || null
        };
    }, seededState.lastState);
    assert(
        diagnosis.strategy === '3_bucket_jilge'
        && diagnosis.realReturnEq < -0.15
        && diagnosis.threeBucket?.isBadYear === true,
        `Browser 3-Bucket bear diagnosis must use the real engine return: ${JSON.stringify(diagnosis)}`
    );
    assert(diagnosis.threeBucket?.is3Bucket === true,
        'Browser 3-Bucket diagnosis must remain attached to the selected strategy');
    smoke.assertNoErrors();
    await smoke.close();
}

async function runBalanceFiveYearRunwayForcedSale(browser, baseUrl) {
    const smoke = await openSmokePage(browser, baseUrl, 'Balance.html', {
        storage: createBalanceStorage(2025)
    });
    const { page } = smoke;
    await waitBalanceHouseholdList(page);
    const witness = await page.evaluate(async () => {
        const { UIReader } = await import('./app/balance/balance-reader.js');
        const base = UIReader.readAllInputs();
        const detailledTranches = [{
            trancheId: 'runway-witness:eq',
            schemaVersion: 2,
            sourceProfileId: 'runway-witness',
            marketValue: 500000,
            costBasis: 250000,
            shares: 1000,
            purchasePrice: 250,
            currentPrice: 500,
            purchaseDate: '2000-01-01',
            type: 'aktien_alt',
            category: 'equity',
            tqf: 0.3,
            taxExempt: false
        }];
        const run = liquidityRunwayYears => window.EngineAPI.simulateSingleYear({
            ...base,
            floorBedarf: 12000,
            flexBedarf: 24000,
            tagesgeld: 100000,
            geldmarktEtf: 0,
            aktuelleLiquiditaet: 100000,
            depotwertAlt: 500000,
            depotwertNeu: 0,
            costBasisAlt: 250000,
            detailledTranches,
            liquidityRunwayYears
        }, null);
        const project = result => ({
            error: result?.error?.message || null,
            configuredRunwayYears: result?.input?.liquidityRunwayYears,
            actionType: result?.ui?.action?.type || 'NONE',
            grossSale: Array.isArray(result?.ui?.action?.quellen)
                ? result.ui.action.quellen.reduce((sum, entry) => sum + (Number(entry.brutto) || 0), 0)
                : 0
        });
        return { oneYear: project(run(1)), fiveYears: project(run(5)) };
    });
    assert(!witness.oneYear.error && !witness.fiveYears.error,
        `Runway forced-sale witness must execute without engine errors: ${JSON.stringify(witness)}`);
    assert(Math.abs(witness.oneYear.grossSale - 50000) <= 0.01,
        `One-year runway control arm must pin the documented 50,000 EUR gross sale: ${JSON.stringify(witness)}`);
    assert(Math.abs(witness.fiveYears.grossSale - 80000) <= 0.01,
        `Five-year runway arm must pin the Slice-17 post-policy 80,000 EUR gross sale: ${JSON.stringify(witness)}`);
    assert(witness.oneYear.configuredRunwayYears === 1 && witness.fiveYears.configuredRunwayYears === 5,
        `Forced-sale witness must preserve both configured runway arms end to end: ${JSON.stringify(witness)}`);
    smoke.assertNoErrors();
    await smoke.close();
}

