        assert(await page.locator('#navigationGuardLeave').textContent() === 'Verwerfen', 'Dirty-Schließen bestätigt Verwerfen');
        assert(await page.locator('#navigationGuardDescription').textContent() === 'Ungespeicherte Eingaben gehen verloren – trotzdem verwerfen?', 'Dirty-Schließen beschreibt den Eingabeverlust');
