function balanceAgeEvidence(raw) { return JSON.parse(raw).personInputEvidence?.aktuellesAlter; }

function importNavigationEntry(kind) { return kind === 'csv' ? 'Balance.html' : 'Daten-Sicherung.html'; }
async function waitForImportNavigationReady(page, kind) {
    if (kind !== 'csv' && new URL(page.url()).pathname.endsWith('/Daten-Sicherung.html')) {
        await waitForPageCondition(page, () => document.documentElement.dataset.dataReady === 'true');
    } else { await waitBalanceHouseholdList(page); await waitForWealthBrowserIdle(page); }
}
async function readImportSnapshots(page) {
    return page.evaluate(() => new Promise((resolve, reject) => {
        const request = indexedDB.open('ruhestand-suite');
        request.onerror = () => reject(request.error);
        request.onsuccess = () => {
            const db = request.result;
            const read = db.transaction('snapshots').objectStore('snapshots').getAll();
            read.onerror = () => { db.close(); reject(read.error); };
            read.onsuccess = () => { db.close(); resolve(read.result); };
        };
    }));
}
async function restoreFullImportRecovery(page, snapshots, before) {
    const recovery = snapshots.find(row => row.snapshot.kind === 'full-backup-import-recovery');
    assert(recovery, 'Vollimport besitzt bestätigten archivierten Recoverypunkt');
    await page.locator('.suite-navigation a[href="Balance.html"]').click();
    await page.waitForURL('**/Balance.html');
    await waitForImportNavigationReady(page, 'json');
    const expectedInputs = JSON.parse(before).inputs;
    const changedFloor = expectedInputs.floorBedarf + 1000;
    // Das Floor-Feld liegt im Reiter „Einstellungen & Strategie“.
    await activateSuiteSection(page, 'strategy');
    await page.locator('#balancePlanTrialStart').click();
    await page.locator('#floorBedarf').fill(String(changedFloor));
    await page.locator('#floorBedarf').press('Tab');
    await waitForWealthBrowserIdle(page);
    await page.locator('#balancePlanTrialAdopt').click();
    await page.locator('#pageChoiceDialog').getByRole('button', { name: 'Auswahl in den Plan übernehmen', exact: true }).click();
    // Die bewusste Auswahl übernimmt Floor in den gemeinsamen Plan.
    await waitForBrowserValue(() => readIndexedDb(page, 'kv', HOUSEHOLD_PLAN_KEY),
        row => row !== null && Object.values(JSON.parse(row.value).entries || {}).some(entry => entry.values?.floorBedarf === changedFloor),
        'Vollimport-Recovery wartet auf den bestätigten geänderten Planfloor');
    await activateSuiteSection(page, 'strategy');
    await openDataBrowser(page);
    const documentId = await page.evaluate(() => {
        window.__importRecoveryDocument = crypto.randomUUID();
        return window.__importRecoveryDocument;
    });
    await page.locator(`[data-restore-preview="${recovery.snapshot.id}"]`).click();
    await page.locator('#dataRestorePreview').waitFor({ state: 'visible' });
    await page.locator('#dataRestoreConfirm').click();
    await page.waitForFunction(id => window.__importRecoveryDocument !== id, documentId);
    await waitForImportNavigationReady(page, 'json');
    const restoredInputs = JSON.parse((await readIndexedDb(page, 'kv', BALANCE_STATE_KEY)).value).inputs;
    assert(['aktuellesAlter', 'floorBedarf', 'flexBedarf', 'tagesgeld', 'depotwertAlt', 'depotwertNeu']
        .every(key => restoredInputs[key] === expectedInputs[key]),
        'Echte Balance-Wiederherstellung bestätigt den Vollimport-Recoverybestand');
    assert((await readIndexedDb(page, 'kv', HOUSEHOLD_PLAN_KEY))?.value === recovery.snapshot.records[HOUSEHOLD_PLAN_KEY],
        'Vollrecovery stellt den gemeinsamen Plan samt Floor bytegleich wieder her');
    assert((await readIndexedDb(page, 'kv', 'depot_tranchen'))?.value === recovery.snapshot.records.depot_tranchen,
        'Vollrecovery stellt auch archivierte Tranchenbytes über Balance wieder her');
    for (const row of snapshots) {
        const archived = await readIndexedDb(page, 'snapshots', row.snapshot.id);
        assert(JSON.stringify(archived.snapshot.records) === JSON.stringify(row.snapshot.records),
            'Balance-Restore erhält archivierte Recoveryrecords bytegleich');
    }
}

// Nur Browsertest: Die Pause liegt vor dem Öffnen der IndexedDB-Transaktion.
// Startup und Fixtureanlage zählen erst nach expliziter Aktivierung des Vorgangs.
async function installReplaceAdapterBarrier(context, { probeKey, stage, ownerDescription, failRollback = false }) {
    await context.addInitScript(({ probeKey, stage, ownerDescription }) => {
        window[probeKey] = { stage, ownerDescription, active: false, entered: false,
            held: false, release: null, writes: 0, owner: null };
    }, { probeKey, stage, ownerDescription });
    await context.route('**/app/shared/persistence-adapter-indexeddb.js', async route => {
        const response = await route.fetch();
        const source = await response.text();
        const anchor = 'async replaceLiveRecords(records, options = {}) {';
        assert(source.split(anchor).length === 2, 'Replacebarriere findet genau einen echten Adaptereintritt');
        const body = source.replace(anchor, `${anchor}
            const probe = window[${JSON.stringify(probeKey)}];
            if (probe?.active && !probe.held) {
                probe.writes++;
                const { getPageNavigationGuard } = await import('./navigation-guard-dialog.js');
                const commits = getPageNavigationGuard().reasons().filter(reason => reason.phase === 'commit'
                    && reason.owner?.description === probe.ownerDescription);
                if (probe.writes === 1) probe.owner = commits.length === 1 ? commits[0].owner : null;
                if (probe.writes === (probe.stage === 'rollback' ? 2 : 1)) {
                    probe.held = true; probe.entered = true;
                    await new Promise(resolve => { probe.release = () => { probe.active = false; resolve(); }; });
                    if (${failRollback} && probe.stage === 'rollback') throw new Error('SYNTHETIC_ROLLBACK_FAILED');
                }
            }`);
        await route.fulfill({ response, body });
    });
}

async function activateReplaceAdapterBarrier(page, probeKey) {
    await page.evaluate(probeKey => {
        const probe = window[probeKey];
        probe.writes = 0; probe.entered = false; probe.held = false;
        probe.release = null; probe.owner = null; probe.active = true;
    }, probeKey);
}

async function assertReplaceCommitOwner(page, probeKey, stage) {
    assert(await page.evaluate(async ({ probeKey, stage }) => {
        const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
        const probe = window[probeKey];
        const commits = getPageNavigationGuard().reasons().filter(reason => reason.phase === 'commit');
        return probe.active && probe.held && probe.entered && probe.writes === (stage === 'rollback' ? 2 : 1)
            && probe.owner?.description === probe.ownerDescription
            && commits.length === 1 && commits[0].owner === probe.owner;
    }, { probeKey, stage }), `${stage}: echte Adapterpause hält den zuständigen Import-/Restorecommit einschließlich Rollback`);
}

// Sortierte Schlüssel; sämtliche gespeicherten Werte bleiben unnormalisierte Strings.
async function readLiveRecordBytes(page) {
    return page.evaluate(() => new Promise((resolve, reject) => {
        const request = indexedDB.open('ruhestand-suite');
        request.onerror = () => reject(request.error);
        request.onsuccess = () => {
            const db = request.result;
            const read = db.transaction('kv').objectStore('kv').getAll();
            read.onerror = () => { db.close(); reject(read.error); };
            read.onsuccess = () => { db.close(); resolve(JSON.stringify(read.result.map(row => [row.key, row.value])
                .sort(([a], [b]) => a.localeCompare(b)))); };
        };
    }));
}

async function createImportNavigationProbe(browser, baseUrl, { kind, stage, rollbackFails = false }) {
    const smoke = await createPage(browser, 'Navigation guard imports', {
        storage: createBalanceStorage(2026), observeWealthUpdates: true,
        fixedTime: '2027-01-15T12:00:00+01:00'
    });
    if (['write', 'rollback'].includes(stage)) await installReplaceAdapterBarrier(smoke.context, {
        // Der Vollimport committet über guard.reload und besitzt deshalb die Navigationsmutation.
        probeKey: '__importNavigationProbe', stage, failRollback: rollbackFails, ownerDescription: kind === 'full' ? 'navigation-mutation' : 'persistence-operation'
    });
    // Fehler nach dem tatsächlichen JSON-/CSV-Replace, ohne den Handler zu ersetzen.
    if (stage === 'rollback' && kind !== 'full') await smoke.context.route('**/app/balance/balance-file-service.js', async route => {
        const response = await route.fetch();
        const body = (await response.text()).replace('if (!final?.ok)',
            "if (!final?.ok || window.__importNavigationProbe?.stage === 'rollback')");
        await route.fulfill({ response, body });
    });
    await smoke.page.goto(`${baseUrl}/${importNavigationEntry(kind)}`);
    await waitForImportNavigationReady(smoke.page, kind);
    const payload = await smoke.page.evaluate(async ({ kind, stage }) => {
        const { PersistenceFacade } = await import('./app/shared/persistence-facade.js');
        const { SnapshotArchive } = await import('./app/shared/snapshot-archive.js');
        const { createBalanceExportDocument } = await import('./app/balance/balance-binder-imports.js');
        const { buildFullPersistenceBackup } = await import('./app/shared/persistence-backup.js');
        const probe = window.__importNavigationProbe ||= { stage, entered: false, release: null, writes: 0 };
        const pause = async () => { probe.entered = true; await new Promise(resolve => { probe.release = resolve; }); };
        const state = JSON.parse(PersistenceFacade.getItemSync('ruhestandsmodellValues_v29_guardrails'));
        const document = createBalanceExportDocument({ ...state, inputs: { ...state.inputs, aktuellesAlter: 68 } });
        const backup = buildFullPersistenceBackup();
        backup.records.ruhestandsmodellValues_v29_guardrails = JSON.stringify(document.payload);
        // Personenschema 1 kennt kein gespeichertes Alter mehr; das Geburtsdatum trägt die Änderung.
        backup.records.profile_geburtsdatum = '1957-03-14';
        const backupRegistry = JSON.parse(backup.records.rs_profiles_v1);
        const activeId = backup.records.rs_active_profile;
        backupRegistry.profiles[activeId].data.ruhestandsmodellValues_v29_guardrails = backup.records.ruhestandsmodellValues_v29_guardrails;
        backupRegistry.profiles[activeId].data.profile_geburtsdatum = '1957-03-14';
        backup.records.rs_profiles_v1 = JSON.stringify(backupRegistry);
        if (kind === 'csv') for (const [id, value] of Object.entries({ marketCsvMode: 'current', marketCsvTargetYear: '2026', marketCsvExpectedAsOf: '2026-12-30', marketCsvInstrument: 'synthetic.de' })) {
            window.document.getElementById(id).value = value;
        }
        if (stage === 'file') {
            if (kind === 'full') {
                const original = FileReader.prototype.readAsText;
                FileReader.prototype.readAsText = function(...args) { pause().then(() => original.apply(this, args)); };
            } else {
                const original = File.prototype.text;
                File.prototype.text = async function() { await pause(); return original.call(this); };
            }
        }
        if (stage === 'snapshotRead') {
            const original = SnapshotArchive.readSnapshot;
            SnapshotArchive.readSnapshot = async (...args) => { await pause(); return original(...args); };
        }
        if (stage === 'flush') {
            const original = PersistenceFacade.flush;
            let first = true;
            PersistenceFacade.flush = async (...args) => { if (first) { first = false; await pause(); } return original(...args); };
        }
        if (stage === 'probelauf') {
            const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
            const guard = getPageNavigationGuard();
            const originalReload = guard.reload, originalReplace = PersistenceFacade.replaceRecordsTransactional;
            probe.mutations = 0;
            guard.reload = async options => {
                // Der echte Binder hat Datei und Recovery bereits vorbereitet. Sein mutate läuft erst nach Freigabe.
                await pause();
                return originalReload({ ...options, mutate: async operation => {
                    probe.mutations++;
                    return options.mutate(operation);
                } });
            };
            PersistenceFacade.replaceRecordsTransactional = (...args) => { probe.writes++; return originalReplace(...args); };
            probe.cleanup = () => { guard.reload = originalReload; PersistenceFacade.replaceRecordsTransactional = originalReplace; };
        }
        if (stage === 'write' || stage === 'rollback') {
            if (stage === 'rollback' && kind === 'full') {
                const transactional = PersistenceFacade.replaceRecordsTransactional;
                PersistenceFacade.replaceRecordsTransactional = (...args) => {
                    args[1] = { ...args[1], postValidate: () => ({ ok: false, message: 'SYNTHETIC_IMPORT_POSTVALIDATION' }) };
                    return transactional(...args);
                };
            }
        }
        return JSON.stringify(kind === 'full' ? backup : document);
    }, { kind, stage });
    const csv = 'Datum;Schluss\n30.12.2023;100\n30.12.2024;110\n30.12.2025;120\n30.12.2026;130';
    smoke.start = async () => {
        // Echte Nutzeraktivierung für den nativen beforeunload-Vertrag.
        const file = { name: kind === 'csv' ? 'synthetic.csv' : 'synthetic.json', mimeType: kind === 'csv' ? 'text/csv' : 'application/json', buffer: Buffer.from(kind === 'csv' ? csv : payload) };
        if (['write', 'rollback'].includes(stage)) await activateReplaceAdapterBarrier(smoke.page, '__importNavigationProbe');
        if (kind === 'full') {
            const chooser = smoke.page.waitForEvent('filechooser');
            await smoke.page.locator('#fullBackupImportBtn').click();
            const input = await chooser;
            assert(await input.element().getAttribute('id') === 'fullBackupImportFile', 'Vollimport bedient tatsächliches Dateifeld der Sicherungsseite');
            await input.setFiles(file);
            if (stage !== 'file') await answerPageDialog(smoke.page, { label: 'Backup importieren' });
        } else {
            if (kind === 'json') {
                await smoke.page.locator('#balance-austausch > summary').click();
                await smoke.page.locator('#dataBalanceFile').setInputFiles(file);
                if (stage !== 'file') await answerPageDialog(smoke.page, { label: 'Balance importieren' });
            } else { await smoke.page.locator('.tab-btn[data-tab="strategy"]').click(); await smoke.page.locator('#csvFileInput').setInputFiles(file); }
        }
        await smoke.page.waitForFunction(() => window.__importNavigationProbe.entered);
        if (['write', 'rollback'].includes(stage)) await assertReplaceCommitOwner(smoke.page, '__importNavigationProbe', stage);
    };
    return smoke;
}

async function runNavigationGuardImports(browser, baseUrl) {
    // Markt-CSV-Bedienung entfiel auf Nutzerentscheid (05.10.2026, Inventar B06/B10/B11/B24); Voll- und JSON-Import bleiben geschützt.
    for (const kind of ['full', 'json']) for (const stage of ['file', 'flush', 'snapshotRead', 'write', 'rollback']) {
        const smoke = await createImportNavigationProbe(browser, baseUrl, { kind, stage });
        try {
            const { page } = smoke;
            const before = (await readIndexedDb(page, 'kv', BALANCE_STATE_KEY)).value;
            const channel = await page.evaluate(() => window.name);
            // Vergleichsbasis ist der bestätigte Livebestand vor dem Commit: Der Importweg sichert vorab das
            // aktive Profil (mit normalisierten Haushaltsfeldern) und schreibt entprellte Startwrites.
            if (stage === 'rollback') await page.evaluate(async () => {
                const { saveCurrentProfileFromLocalStorage } = await import('./app/profile/profile-storage.js');
                const { PersistenceFacade } = await import('./app/shared/persistence-facade.js');
                saveCurrentProfileFromLocalStorage();
                await PersistenceFacade.flush();
            });
            const liveBefore = await readLiveRecordBytes(page);
            await smoke.start();
            const snapshotsBeforeEnd = stage === 'rollback' ? await readImportSnapshots(page) : null;
            const link = page.locator('.suite-navigation a[href="Handbuch.html"]');
            await link.focus(); await page.keyboard.press('Enter');
            if (['file', 'flush', 'snapshotRead'].includes(stage)) {
                await page.locator('#navigationGuardDialog[open]').waitFor();
                await page.locator('#navigationGuardStay').click();
                await waitForNavigationDecisionSettled(page);
                assert(await page.evaluate(() => window.__importNavigationProbe.release !== null), 'Bleiben erhält die echte Importvorbereitung');
                await link.focus(); await page.keyboard.press('Enter');
                await page.locator('#navigationGuardLeave').click();
                await initializeBrowserSmokeNavigationGuard(page);
                await page.waitForFunction(() => {
                    return window.__browserSmokeNavigationGuard.reasons().some(reason => reason.phase === 'cancelling');
                });
                assert(new URL(page.url()).pathname.endsWith(`/${importNavigationEntry(kind)}`), 'Importkündigung wartet vor App-Wechsel auf Handlerende');
                assert(await page.evaluate(() => window.name) === channel, 'Vor Abbruchende startet kein Bundle-Handoff');
                await page.evaluate(() => window.__importNavigationProbe.release());
                await page.waitForURL('**/Handbuch.html');
                assert((await readIndexedDb(page, 'kv', BALANCE_STATE_KEY)).value === before, 'Bestätigte Kündigung verhindert jeden späteren Importcommit');
            } else {
                assert(new URL(page.url()).pathname.endsWith(`/${importNavigationEntry(kind)}`), 'App-Enter bleibt während echtem Importwrite/Rollback gesperrt');
                assert(await page.locator('#navigationGuardDialog').isHidden(), 'Importcommit zeigt keinen Verlustdialog');
                assert(await page.locator('#suiteNavigationStatus').isVisible(), 'Importcommit meldet Wartehinweis ortsfest');
                await nativeNavigationAttempt(page, { kind: 'reload', accept: false, verify: async () => {
                    assert(await page.evaluate(async () => {
                        const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
                        return getPageNavigationGuard().reasons().some(reason => reason.phase === 'commit');
                    }), 'Echte native Ablehnung erhält den äußeren Commitbesitzer');
                } });
                const documentId = await page.evaluate(() => window.__nativeDocumentProbe);
                let reloads = 0;
                const countReload = frame => { if (frame === page.mainFrame()) reloads++; };
                page.on('framenavigated', countReload);
                await page.evaluate(() => window.__importNavigationProbe.release());
                if (stage === 'write' && kind === 'full') {
                    await page.waitForFunction(id => window.__nativeDocumentProbe !== id, documentId);
                    await waitForImportNavigationReady(page, kind);
                    assert(reloads === 1, 'Erfolgreicher Vollimport lädt genau einmal neu');
                    assert(balanceAgeEvidence((await readIndexedDb(page, 'kv', BALANCE_STATE_KEY)).value) === 68,
                        'Vollimport lädt ohne Zusatzflush erfolgreich aus dem Backend neu');
                    assert(await page.evaluate(() => window.name) === channel, 'Erfolgreicher Vollimportreload exportiert kein Profilbundle');
                } else {
                    await initializeBrowserSmokeNavigationGuard(page);
                    await page.waitForFunction(() => {
                        return window.__browserSmokeNavigationGuard.reasons().length === 0;
                    });
                    if (stage === 'rollback') {
                        assert((await readIndexedDb(page, 'kv', BALANCE_STATE_KEY)).value === before, 'Echter verzögerter Importrollback stellt Bestandsbytes wieder her');
                        const liveAfter = await readLiveRecordBytes(page);
                        if (kind === 'full') {
                            assert(liveAfter === liveBefore, 'Importrollback stellt sämtliche vorherigen Livebytes wieder her');
                        } else {
                            // Die Balance-Wiederherstellung frischt danach bewusst die Profilkopie des aktiven Profils
                            // aus dem Livebestand auf (normalisierte Haushaltsfelder, updatedAt). Alles andere bleibt bytegleich,
                            // die Profilkopie entspricht inhaltlich dem wiederhergestellten Balance-State.
                            const rows = raw => Object.fromEntries(JSON.parse(raw));
                            const [a, b] = [rows(liveBefore), rows(liveAfter)];
                            // Seit Daten & Sicherung liest der Importkontext Balance erstmals auf dieser Seite; loadState() setzt dabei
                            // den idempotenten Migrationsmarker wie jeder erste Balance-Start. Er ist keine Importänderung.
                            if (!Object.hasOwn(a, 'migration_v29_inflation_sanitized') && b.migration_v29_inflation_sanitized === '1') delete b.migration_v29_inflation_sanitized;
                            const activeId = b.rs_current_profile || b.rs_active_profile;
                            const withoutActiveCopy = raw => { const r = JSON.parse(raw); delete r.profiles?.[activeId]?.data; delete r.profiles?.[activeId]?.meta?.updatedAt; return JSON.stringify(r); };
                            assert(JSON.stringify(Object.keys(a)) === JSON.stringify(Object.keys(b))
                                && Object.keys(a).every(key => key === 'rs_profiles_v1' ? withoutActiveCopy(a[key]) === withoutActiveCopy(b[key]) : a[key] === b[key]),
                            'Importrollback stellt sämtliche vorherigen Livebytes außer der bewusst aufgefrischten Profilkopie wieder her');
                            const copy = JSON.parse(JSON.parse(b.rs_profiles_v1).profiles[activeId].data[BALANCE_STATE_KEY]);
                            assert(JSON.stringify(copy.inputs) === JSON.stringify(JSON.parse(b[BALANCE_STATE_KEY]).inputs),
                                'Aufgefrischte Profilkopie entspricht dem wiederhergestellten Balance-State');
                        }
                        assert(JSON.stringify(await readImportSnapshots(page)) === JSON.stringify(snapshotsBeforeEnd),
                            'Importrollback erhält sämtliche archivierten Snapshotrecords bytegleich');
                        const errorHost = kind === 'full' ? '#fullBackupStatus' : '#dataExchangeStatus';
                        assert(await page.locator(errorHost).isVisible(), 'Importfehler bleibt an seinem Aktionsort erreichbar');
                        assert(await readIndexedDb(page, 'snapshots', null) >= 1, 'Recovery-Snapshot bleibt nach Fehler vorhanden');
                        if (kind === 'full') {
                            assert((await page.locator(errorHost).textContent()).includes('Wiederherstellungspunkt')
                                && (await page.locator(errorHost).textContent()).includes('Daten & Sicherung'),
                                'Startseite nennt Recoverypunkt und bestehenden Balance-Wiederherstellungsweg');
                            const importText = await page.locator(errorHost).textContent();
                            assert(importText.includes('Dein bisheriger Stand ist unverändert.')
                                && !/snapshot_|\[restore_rolled_back\]|\[rollback_failed\]|SYNTHETIC_IMPORT_POSTVALIDATION/.test(importText),
                                'Vollrollback bestätigt unveränderten Stand ohne technische Restoredetails');
                            assert(JSON.stringify(await readImportSnapshots(page)) === JSON.stringify(snapshotsBeforeEnd),
                                'Vollrollback erhält gesamten archivierten Snapshotbestand bytegleich');
                            // Bekannt rot (A3): Nach dem fehlgeschlagenen Vollimport aktualisiert die Seite die Punkteliste nicht.
                            assert(await page.locator('[data-restore-preview]').count() >= 1, 'Recovery ist auf der Sicherungsseite erreichbar');
                            await restoreFullImportRecovery(page, snapshotsBeforeEnd, before);
                        } else {
                            // Ohne künstliches Listenereignis: Der neue Punkt muss ohne Reload erreichbar sein (bekannt rot: A3).
                            assert(await page.locator('[data-restore-preview]').count() >= 1, 'Neuer Import-Recoverypunkt bleibt ohne Reload erreichbar');
                        }
                    }
                }
            }
            smoke.assertNoErrors(['SYNTHETIC_IMPORT_POSTVALIDATION', 'Import', 'CSV', 'Persistenz-Restore']);
        } finally { await smoke.close(); }
    }
    // Nach echter Dateivorbereitung und Recovery, vor guard.reload/mutate: Probelaufsperre ohne Ersatz/Reload.
    const probelaufBlocked = await createImportNavigationProbe(browser, baseUrl, { kind: 'full', stage: 'probelauf' });
    try {
        const { page } = probelaufBlocked;
        await probelaufBlocked.start();
        const before = await readLiveRecordBytes(page), snapshots = await readImportSnapshots(page);
        const recovery = snapshots.find(row => row.snapshot.kind === SNAPSHOT_KINDS.fullBackupImportRecovery);
        assert(recovery, 'Probelaufrennen erreicht guard.reload erst nach dauerhaft angelegtem Recoverypunkt');
        assert(balanceAgeEvidence((await readIndexedDb(page, 'kv', BALANCE_STATE_KEY)).value) !== 68,
            'Vor Freigabe ist der Vollimportzielbestand noch nicht geschrieben');
        const documentId = await page.evaluate(() => window.__fullImportBlockedDocument = crypto.randomUUID());
        let reloads = 0;
        const onNavigation = frame => { if (frame === page.mainFrame()) reloads++; };
        page.on('framenavigated', onNavigation);
        try {
            await page.evaluate(async () => {
                const { getProbelaufController } = await import('./app/shared/probelauf-state.js');
                // Tatsächliche Koordinatorsperre; keine vorgefertigte Importantwort.
                getProbelaufController(document).invalidate();
                window.__importNavigationProbe.release();
            });
            await waitForPageCondition(page, () => document.getElementById('fullBackupStatus')?.dataset.kind === 'error');
            await initializeBrowserSmokeNavigationGuard(page);
            await page.waitForFunction(() => window.__browserSmokeNavigationGuard.reasons().length === 0);
            const status = page.locator('#fullBackupStatus'), text = await status.textContent();
            assert(await status.isVisible() && text.includes('Probelauf') && text.includes('Probelauf beenden')
                && !text.includes('erneut versuchen'), 'Sichtbarer Binderstatus nennt Probelauf beenden mit Fehlerstatus');
            assert(!text.includes(recovery.snapshot.id) && !/probelauf_backup_|\[|wurde angelegt/.test(text),
                'Frühe Dienstsperre ohne übernommene Kennung behauptet keine Anlage und zeigt keine technischen Details');
            const probe = await page.evaluate(() => ({ mutations: window.__importNavigationProbe.mutations,
                writes: window.__importNavigationProbe.writes, documentId: window.__fullImportBlockedDocument }));
            assert(probe.mutations === 1 && probe.writes === 0, 'Echter Binder-mutator verweigert den Import vor dem transaktionalen Ersatz');
            assert(reloads === 0 && probe.documentId === documentId, 'Probelaufsperre löst keinen Erfolgsreload aus');
            assert(await readLiveRecordBytes(page) === before, 'Probelaufsperre erhält sämtliche fachlichen Backendbytes');
            assert(JSON.stringify(await readImportSnapshots(page)) === JSON.stringify(snapshots),
                'Vorbereiteter Recoverypunkt bleibt bytegleich lesbar, kein zusätzlicher Punkt');
            probelaufBlocked.assertNoErrors();
        } finally { page.off('framenavigated', onNavigation); }
    } finally {
        try { await probelaufBlocked.page.evaluate(() => window.__importNavigationProbe?.cleanup?.()); }
        finally { await probelaufBlocked.close(); }
    }
    // Echter zweiter Adapterwrite scheitert: der Status darf keinen unveränderten Stand zusagen.
    const failedRollback = await createImportNavigationProbe(browser, baseUrl, { kind: 'full', stage: 'rollback', rollbackFails: true });
    try {
        const { page } = failedRollback;
        await failedRollback.start();
        await page.evaluate(() => window.__importNavigationProbe.release());
        await waitForPageCondition(page, () => document.getElementById('fullBackupStatus')?.dataset.kind === 'error');
        const text = await page.locator('#fullBackupStatus').textContent();
        assert(text.includes('nicht bestätigt') && text.includes('Wiederherstellungspunkt') && text.includes('Daten & Sicherung')
            && text.includes('wiederherstellen') && !text.includes('ist unverändert')
            && !/snapshot_|\[rollback_failed\]|SYNTHETIC/.test(text),
            'Unbestätigter Vollrollback nennt nötige Wiederherstellung ohne technische Details oder Unverändert-Zusage');
        assert(await readIndexedDb(page, 'snapshots', null) >= 1, 'Unbestätigter Rollback erhält erreichbaren Recoverypunkt');
        failedRollback.assertNoErrors(['SYNTHETIC_ROLLBACK_FAILED', 'Import', 'Persistenz-Restore']);
    } finally { await failedRollback.close(); }
}

async function runNavigationGuardImportsNative(browser, baseUrl) {
    // Markt-CSV-Bedienung entfiel auf Nutzerentscheid (05.10.2026, Inventar B06/B10/B11/B24); Voll- und JSON-Import bleiben geschützt.
    for (const kind of ['full', 'json']) for (const stage of ['file', 'flush', 'snapshotRead', 'write', 'rollback']) {
        const smoke = await createImportNavigationProbe(browser, baseUrl, { kind, stage });
        try {
            await smoke.start();
            await nativeNavigationAttempt(smoke.page, { kind: 'reload', accept: true, verify: async () => {
                assert(new URL(smoke.page.url()).pathname.endsWith(`/${importNavigationEntry(kind)}`), 'Nativer Reload bleibt auf der tatsächlichen Importseite');
                await waitForImportNavigationReady(smoke.page, kind);
                assert(await smoke.page.evaluate(async () => {
                    const { getPageNavigationGuard } = await import('./app/shared/navigation-guard-dialog.js');
                    return getPageNavigationGuard().reasons().length === 0;
                }), 'Echte native Zustimmung hinterlässt keinen flüchtigen Dauerbesitzer');
                const snapshots = await readIndexedDb(smoke.page, 'snapshots', null);
                if (['snapshotRead', 'write', 'rollback'].includes(stage)) assert(snapshots >= 1,
                    'Vor dem nativen Verlassen bestätigter Recoverypunkt bleibt erreichbar');
                else assert(snapshots === 0, 'Dateilesen und erster Vorbereitungsflush erzeugen noch keinen Recoverypunkt');
            } });
            smoke.assertNoErrors(['SYNTHETIC_IMPORT_POSTVALIDATION', 'Import', 'CSV']);
        } finally { await smoke.close(); }
    }
}

async function runNavigationGuardSnapshotRestore(browser, baseUrl) {
    for (const full of [false, true]) for (const stage of ['read', 'write', 'rollback', 'input']) {
        const smoke = await createPage(browser, 'Navigation guard snapshot restore', { storage: createBalanceStorage(2026), fixedTime: '2027-01-15T12:00:00+01:00' });
        try {
            const { page } = smoke;
            if (stage !== 'read') await installReplaceAdapterBarrier(smoke.context, { probeKey: '__snapshotNavigationProbe', stage, ownerDescription: 'navigation-mutation' });
            await page.goto(`${baseUrl}/Daten-Sicherung.html`); await openDataBrowser(page);
            const before = await readLiveRecordBytes(page);
            const saved = await page.evaluate(async full => {
                const { SnapshotArchive: a } = await import('./app/shared/snapshot-archive.js');
                const { PersistenceFacade: p } = await import('./app/shared/persistence-facade.js');
                const records = await p.readPersistedRecords(); records.profile_geburtsdatum = '1957-03-14';
                const state = JSON.parse(records.ruhestandsmodellValues_v29_guardrails); state.personInputEvidence = { ...state.personInputEvidence, aktuellesAlter: 68 };
                records.ruhestandsmodellValues_v29_guardrails = JSON.stringify(state);
                const registry = JSON.parse(records.rs_profiles_v1); registry.profiles[records.rs_current_profile].data.profile_geburtsdatum = records.profile_geburtsdatum; records.rs_profiles_v1 = JSON.stringify(registry);
                const saved = await a.createSnapshot({ id: 'synthetic-restore', activeProfileId: records.rs_current_profile, kind: full ? 'full-backup-import-recovery' : 'manual', records });
                document.dispatchEvent(new Event('overview-backup-changed')); return saved;
            }, full);
            const preview = page.locator(`[data-restore-preview="${saved.id}"]`); await preview.waitFor();
            if (stage === 'read') {
                await page.evaluate(async () => {
                    const { SnapshotArchive: a } = await import('./app/shared/snapshot-archive.js'); const read = a.readSnapshot;
                    window.__snapshotReadEntered = false;
                    a.readSnapshot = async (...args) => { window.__snapshotReadEntered = true; await new Promise(() => {}); return read(...args); };
                });
                await preview.click(); await waitForPageCondition(page, () => window.__snapshotReadEntered);
                await page.locator('.suite-navigation a[href="Handbuch.html"]').click(); await page.waitForURL('**/Handbuch.html');
                assert(await readLiveRecordBytes(page) === before, 'Navigation während schreibfreier Vorschau startet keinen Restorewrite');
            } else {
                await preview.click(); await page.locator('#dataRestorePreview').waitFor({ state: 'visible' });
                if (stage === 'rollback') await page.evaluate(async () => {
                    const { PersistenceFacade: p } = await import('./app/shared/persistence-facade.js'); const replace = p.replaceRecordsTransactional;
                    p.replaceRecordsTransactional = (records, options) => replace(records, { ...options, postValidate: () => ({ ok: false, message: 'SYNTHETIC_RESTORE_POSTVALIDATION' }) });
                });
                await activateReplaceAdapterBarrier(page, '__snapshotNavigationProbe'); await page.locator('#dataRestoreConfirm').click();
                await waitForPageCondition(page, () => window.__snapshotNavigationProbe.entered); await assertReplaceCommitOwner(page, '__snapshotNavigationProbe', stage);
                await page.locator('.suite-navigation a[href="Handbuch.html"]').click();
                assert(new URL(page.url()).pathname.endsWith('/Daten-Sicherung.html'), 'Appnavigation bleibt während Restorewrite und Rollback gesperrt');
                await nativeNavigationAttempt(page, { kind: 'reload', accept: false, verify: async () => {
                    assert(await page.evaluate(async () => (await import('./app/shared/navigation-guard-dialog.js')).getPageNavigationGuard().reasons().some(reason => reason.phase === 'commit')), 'Native Ablehnung erhält Restorebesitzer');
                } });
                let reloads = 0; const count = frame => { if (frame === page.mainFrame()) reloads++; }; page.on('framenavigated', count);
                if (stage === 'input') await page.locator('#dataPersonSelect').dispatchEvent('input');
                const loaded = stage === 'write' ? page.waitForEvent('load') : null;
                await page.evaluate(() => window.__snapshotNavigationProbe.release());
                if (stage === 'write') { await loaded; await openDataBrowser(page); assert(reloads === 1, 'Bestätigter Restore lädt genau einmal'); }
                else if (stage === 'input') {
                    // Seit Daten & Sicherung steht im Status eine Nutzermeldung; der Restorewortlaut liegt unter „Technische Details“.
                    await page.locator('#dataRestoreStatus[data-kind="error"]').filter({ hasText: 'Bitte lade die Seite neu' }).waitFor();
                    assert((await page.locator('#dataRestoreTechnical').textContent()).includes('nicht neu geladen'), 'Technische Details nennen den gespeicherten, nicht neu geladenen Stand');
                    assert(reloads === 0 && await page.locator('#dataRestoreConfirm').isDisabled(), 'Neue Eingabe verhindert Reload und sperrt veraltete Restorebedienung');
                } else {
                    await page.locator('#dataRestoreStatus[data-kind="error"]').waitFor();
                    assert(reloads === 0 && await readLiveRecordBytes(page) === before, 'Fehlgeschlagener Restore bestätigt Rollback ohne Reload');
                    assert(await page.locator(`[data-restore-preview="${saved.id}"]`).isEnabled(), 'Recoverypunkt bleibt nach bestätigtem Rollback erreichbar');
                }
                page.off('framenavigated', count);
            }
            const archived = await readIndexedDb(page, 'snapshots', saved.id);
            assert(JSON.stringify(archived.snapshot.records) === JSON.stringify(saved.records), 'Archivierter Zielpunkt bleibt bytegleich');
            smoke.assertNoErrors(['SYNTHETIC_RESTORE_POSTVALIDATION']);
        } finally { await smoke.close(); }
    }
}

