            await page.waitForFunction(() => !document.getElementById('jahresabschlussBtn')?.disabled);
            const failed = await readBalanceBrowserState(page);
            assert(failed.annualPeriodMetadata.pendingCommit.snapshotId === pending.snapshotId,
                'Finalisierungsfehler behält echte Recovery statt Abbruch zu melden');
