        await page.locator('#managerHousehold [data-manager-profile="views-a"]').click(); await expectPerson('views-a');
        assert(await selected().count() === 1, 'Kartenaktion der bereits bearbeiteten Person öffnet wieder ihr Panel');
        await selected().focus(); await page.keyboard.press('End');
        assert(await page.locator('#managerHistoryTab').evaluate(node => node === document.activeElement), 'End bewegt ausschließlich den Reiterfokus');
        await expectPerson('views-a');
        await page.keyboard.press('Home'); await page.keyboard.press('Space'); await expectPlan();
        await page.locator('#managerSectionNav [data-manager-profile="views-b"]').click(); await expectPerson('views-b');
        await page.reload(); await expectPerson('views-a');
        await page.locator('#managerPlanTab').click(); await expectPlan();
        await page.reload(); await expectPerson('views-a');
        await page.goto(`${baseUrl}/depot-tranchen-manager.html?person=views-b#profileTagesgeld`);
        await expectPerson('views-b');
        await waitForPageCondition(page, () => document.activeElement?.id === 'profileTagesgeld');
        assert(await page.locator('#managerAssetsBody').isVisible(), 'Direktlink öffnet Tagesgeld vor sichtbarem Feldfokus');
        await page.evaluate(() => { location.hash = '#haushalt-plan'; }); await expectPlan();
        await page.evaluate(() => { location.hash = '#personendaten'; }); await expectPerson('views-b');
        await waitForPageCondition(page, () => ['profileGeburtsdatum', 'managerBirthDate'].includes(document.activeElement?.id));
        await page.evaluate(() => { location.hash = '#managerDepotTitle'; });
        await waitForPageCondition(page, () => document.activeElement?.id === 'managerDepotTitle');
        await page.evaluate(() => { location.hash = '#managerProfileValues'; });
        await waitForPageCondition(page, () => document.activeElement?.id === 'managerPersonToggle');
        await page.evaluate(() => { location.hash = '#personen'; });
        await page.locator('#managerPeopleModal.active').waitFor();
        await page.locator('#dismissPeopleModalBtn').click();
        await page.locator('#managerPeopleModal.active').waitFor({ state: 'hidden' });
        await page.evaluate(() => { history.replaceState(null, '', '?person=views-a&person=views-c'); location.hash = '#profileTagesgeld'; });
        await expectPerson('views-b');
        assert(await page.locator('#managerSectionNav [aria-selected="true"]').evaluate(tab =>
            document.getElementById(tab.getAttribute('aria-controls'))?.getAttribute('aria-labelledby') === tab.id), 'Ausgewählter Personenreiter und Panel sind gegenseitig verknüpft');
