// Unabhängige Fachwerte für Browserabnahme; kein Orakel aus der Presetquelle.
const browserDynamicValues = {
    off: { dynamicFlex: false, horizonMethod: 'survival_quantile', horizonYears: 30, survivalQuantile: .85, goGoActive: false, goGoMultiplier: 1, longevityMode: 'none', longevityQuantileShift: .05, longevityRelativePct: .05, longevityBufferYears: 2 },
    konservativ: { dynamicFlex: true, horizonMethod: 'survival_quantile', horizonYears: 35, survivalQuantile: .9, goGoActive: false, goGoMultiplier: 1, longevityMode: 'none', longevityQuantileShift: .05, longevityRelativePct: .05, longevityBufferYears: 2 },
    ausgewogen: { dynamicFlex: true, horizonMethod: 'survival_quantile', horizonYears: 30, survivalQuantile: .85, goGoActive: true, goGoMultiplier: 1.1, longevityMode: 'none', longevityQuantileShift: .05, longevityRelativePct: .05, longevityBufferYears: 2 },
    offensiv: { dynamicFlex: true, horizonMethod: 'mean', horizonYears: 25, survivalQuantile: .75, goGoActive: true, goGoMultiplier: 1.2, longevityMode: 'none', longevityQuantileShift: .05, longevityRelativePct: .05, longevityBufferYears: 2 }
};
function browserDynamicRecords(matching, annual = false) {
    const records = annual ? withClosingYearExpenseEvidence(createMusterHaushaltRecords('2026-10-09'), 2026, 'muster_a') : createMusterHaushaltRecords('2026-10-09');
    const entries = Object.values(JSON.parse(records[HOUSEHOLD_PLAN_KEY]).entries);
    const original = { ...entries[0].values, ...browserDynamicValues.ausgewogen, dynamicFlex: matching === 'active',
        goGoMultiplier: matching === 'active' ? 1.2 : matching ? 1.1 : 1.17, longevityRelativePct: .07 };
    records[HOUSEHOLD_PLAN_KEY] = buildPlanRecord(records[HOUSEHOLD_PLAN_KEY], entries.map(entry => ({ scope: entry.scope, values: original }))).raw;
    return { records, original };
}
async function readBrowserDynamicPlan(page) {
    return page.evaluate(async () => {
        const { PersistenceFacade: p } = await import('./app/shared/persistence-facade.js');
        const records = await p.readPersistedRecords();
        const values = Object.values(JSON.parse(records.household_plan_v1).entries).find(entry => entry.scope.kind === 'household').values;
        return { values, raw: records.household_plan_v1, receipt: records.annual_plan_record_v1 || null };
    });
}
async function assertBrowserDynamicDetails(page, root, label) {
    for (const width of [1366, 1920, 390]) {
        await page.setViewportSize({ width, height: 1200 });
        const segment = root.locator('[data-plan-dynamic-presets]');
        assert(await segment.getAttribute('aria-label') === 'Dynamik', label + ': zugängliche Presetgruppe');
        assert((await segment.locator('button').allTextContents()).join(' · ') === 'Aus · Konservativ · Ausgewogen · Offensiv · Benutzerdefiniert', label + ': genau fünf Segmente');
        assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1), label + ': kein äußerer Überlauf ' + width);
        assert(await segment.evaluate(node => [...node.querySelectorAll('button')].every(button => button.getBoundingClientRect().right <= innerWidth + 1)), label + ': Segmentumbruch ' + width);
        await segment.locator('[data-plan-dynamic-preset="custom"]').focus();
        assert(await segment.locator('[data-plan-dynamic-preset="custom"]').evaluate(node => node === document.activeElement), label + ': sichtbarer Segmentfokus');
        await capturePageDialogImage(page, label + '-dynamik-' + width);
    }
}
async function assertBrowserDynamicTyping(page, root, fieldId, label) {
    const field = root.locator('#' + fieldId), details = root.locator('[data-plan-dynamic-details]');
    assert(await details.isVisible() && await field.isEnabled(), label + ': aktive individuelle Basis öffnet ohne Customklick');
    await field.focus(); await page.keyboard.press('ControlOrMeta+A');
    await page.keyboard.type('1,1');
    const check = async text => {
        assert(await details.isVisible() && await field.isEnabled(), label + ': Details bleiben bei ' + text + ' bedienbar');
        assert(await field.evaluate(node => node === document.activeElement), label + ': Faktor behält Fokus bei ' + text);
        assert(await field.inputValue() === text, label + ': vollständiger Text ' + text);
        assert(await root.locator('[data-plan-dynamic-preset="custom"]').getAttribute('aria-pressed') === 'true'
            && await root.locator('[data-plan-dynamic-hint]').isHidden(), label + ': Custom und Hinweis entsprechen offenen Details');
    };
    await check('1,1');
    // Anfügen ohne Locatoraktion, erneuten Fokus oder erneutes fill().
    await page.keyboard.type('5'); await check('1,15');
}
async function readBrowserDynamicRecords(page) {
    return page.evaluate(async () => {
        const { PersistenceFacade: p, persistenceStorage: storage } = await import('./app/shared/persistence-facade.js');
        const sorted = entries => JSON.stringify(entries.sort(([a], [b]) => a.localeCompare(b)));
        return {
            backend: sorted(Object.entries(await p.readPersistedRecords())),
            cache: sorted(Array.from({ length: storage.length }, (_, i) => { const key = storage.key(i); return [key, storage.getItem(key)]; })),
            local: sorted(Object.entries(localStorage))
        };
    });
}
async function assertBrowserDynamicError(page, root, fieldId, label) {
    const field = root.locator('#' + fieldId), error = root.locator('#' + fieldId + '_error');
    assert(await field.inputValue() === 'unlesbar', label + ': Fehlertext exakt erhalten');
    assert(await field.getAttribute('aria-invalid') === 'true', label + ': Feldmarkierung erhalten');
    assert((await error.textContent()).includes('lesbare Zahl'), label + ': Meldung erhalten');
    const visibility = await field.evaluate(field => {
        const root = field.closest('[data-annual-plan-editor], #managerHouseholdPlan');
        const visible = node => {
            for (; node; node = node.parentElement) {
                if (node.hidden) return false;
                if (node === root) return true;
            }
            return false;
        };
        return Boolean(root && [field, field.parentElement, document.getElementById(field.id + '_error')].every(visible));
    });
    assert(visibility && await field.isVisible() && await error.isVisible(), label + ': alle Vorfahren einschließlich Editorwurzel sichtbar');
    assert(await field.isEnabled(), label + ': Faktor aktiviert');
    await field.focus();
    assert(await field.evaluate(node => node === document.activeElement), label + ': Faktor direkt fokussierbar');
}
async function runDynamicFlexVisibleDetailBlurSmoke(browser, baseUrl, annual) {
    const { records, original } = browserDynamicRecords('active', annual);
    const entries = Object.values(JSON.parse(records[HOUSEHOLD_PLAN_KEY]).entries);
    records[HOUSEHOLD_PLAN_KEY] = buildPlanRecord(records[HOUSEHOLD_PLAN_KEY], entries.map(entry => ({ scope: entry.scope,
        values: { ...original, longevityMode: 'buffer_years', longevityBufferYears: 3 } }))).raw;
    const label = (annual ? 'Jahreseditor' : 'Manager') + '/sichtbarer Customblur';
    const smoke = annual
        ? await openSmokePage(browser, baseUrl, 'index.html', { storage: records, fixedTime: '2027-01-02T12:00:00+01:00', annualFixtures: { targetYear: 2026 }, observeWealthUpdates: true })
        : await createPage(browser, label, { storage: records, fixedTime: '2026-10-09T12:00:00Z' });
    const { page } = smoke;
    try {
        let root;
        if (annual) {
            await page.locator('[data-overview-annual]').waitFor(); await waitForWealthBrowserIdle(page);
            await page.locator('[data-overview-annual]').click();
            await prepareBrowserClose(page);
            await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
            const dialog = page.locator('#balanceAnnualClose');
            await dialog.locator('[data-close-dialog-activate="preview"]').click();
            await dialog.locator('[data-annual-plan-toggle]').click();
            root = dialog.locator('[data-annual-plan-editor]');
        } else {
            await page.goto(`${baseUrl}/depot-tranchen-manager.html#haushalt-plan`);
            await waitForPageCondition(page, () => document.getElementById('managerPlan_dynamicFlex')?.disabled === false);
            await waitForPageCondition(page, key => ['complete', 'empty'].includes(JSON.parse(sessionStorage.getItem(key) || 'null')?.status), STARTUP_PRICE_SESSION_KEY);
            root = page.locator('#managerHouseholdPlan');
        }
        const field = root.locator('#' + (annual ? 'annualPlan_' : 'managerPlan_') + 'longevityBufferYears');
        await field.waitFor({ state: 'visible' });
        assert(await field.isEnabled() && await field.getAttribute('aria-invalid') === 'false', label + ': gültiges numerisches Detailfeld aktiviert');
        assert(await root.locator('[data-plan-dynamic-preset="custom"]').getAttribute('aria-pressed') === 'true', label + ': gültige Custombasis erkannt');
        const before = await readBrowserDynamicRecords(page);
        await field.focus();
        assert(await field.evaluate(node => node === document.activeElement), label + ': echtes Feldfocus vor dem Klick');
        // Nur eine bestehende Fläche mit belegtem Treffer verwenden, keine Testfläche einfügen.
        const point = await root.evaluate(root => {
            const nonFocusable = node => {
                for (let current = node; current; current = current.parentElement) {
                    if (current.matches('label, button, input, select, textarea, a[href], [tabindex], [contenteditable]') || current.hidden || current.inert) return false;
                    if (current === root) return true;
                }
                return false;
            };
            for (const node of [root, ...root.querySelectorAll('h3, p, section, div')]) {
                if (!nonFocusable(node) || !node.getClientRects().length) continue;
                const rect = node.getBoundingClientRect();
                for (const [x, y] of [[rect.left + 3, rect.top + 3], [rect.left + rect.width / 2, rect.top + 3],
                    [rect.left + 3, rect.top + rect.height / 2], [rect.left + rect.width / 2, rect.top + rect.height / 2]]) {
                    if (x < 0 || y < 0 || x >= innerWidth || y >= innerHeight || x >= rect.right || y >= rect.bottom) continue;
                    if (document.elementFromPoint(x, y) !== node) continue;
                    window.__dynamicVisibleBlur = { target: node, hit: false, blurred: false, calls: 0, restore: [] };
                    const field = root.querySelector('input[id$="_longevityBufferYears"]');
                    const onBlur = () => { window.__dynamicVisibleBlur.blurred = true; };
                    field.addEventListener('blur', onBlur, { once: true });
                    window.__dynamicVisibleBlur.restore.push(() => field.removeEventListener('blur', onBlur));
                    node.addEventListener('pointerdown', event => {
                        window.__dynamicVisibleBlur.hit = event.isTrusted && event.target === node;
                    }, { once: true });
                    for (const button of root.querySelectorAll('[data-plan-dynamic-preset]')) {
                        const focus = button.focus;
                        button.focus = function(...args) { window.__dynamicVisibleBlur.calls++; return focus.apply(this, args); };
                        window.__dynamicVisibleBlur.restore.push(() => { button.focus = focus; });
                    }
                    return { x, y };
                }
            }
            return null;
        });
        assert(point !== null, label + ': sichtbare nicht fokussierbare Klickfläche innerhalb der Editorwurzel gefunden');
        assert(await page.evaluate(({ x, y }) => document.elementFromPoint(x, y) === window.__dynamicVisibleBlur.target, point), label + ': Geometrie trifft vor Klick exakt die abgesicherte Fläche');
        await page.mouse.click(point.x, point.y);
        const after = await field.evaluate(async node => {
            await new Promise(resolve => setTimeout(resolve, 0));
            const root = node.closest('[data-annual-plan-editor], #managerHouseholdPlan');
            const visible = node => {
                if (!node || node.disabled || !node.getClientRects().length) return false;
                for (; node; node = node.parentElement) {
                    if (node.hidden || node.inert) return false;
                    if (node === root) return true;
                }
                return false;
            };
            const probe = window.__dynamicVisibleBlur;
            const result = { hit: probe.hit, blurred: probe.blurred, body: document.activeElement === document.body,
                // Natürlicher Endfokus: Body oder der nächste fokussierbare Vorfahr der Editorwurzel (Panel mit tabindex, modaler Dialog).
                natural: document.activeElement === document.body || (document.activeElement !== root && Boolean(document.activeElement?.contains(root))), calls: probe.calls,
                activeId: document.activeElement?.id, activeTag: document.activeElement?.tagName,
                visible: [node, node.parentElement, root.querySelector('[data-plan-dynamic-details]')].every(visible) };
            probe.restore.forEach(restore => restore()); delete window.__dynamicVisibleBlur;
            return result;
        });
        assert(after.hit, label + ': vertrauenswürdiger Mausklick trifft tatsächlich die nicht fokussierbare Fläche');
        assert(after.blurred, label + ': Klick löst tatsächlich das native Feldblur aus ' + JSON.stringify(after));
        assert(after.natural && after.calls === 0, label + ': natürlicher Endfokus (Body oder fokussierbarer Vorfahr wie Panel/Dialog) bleibt ohne jeden programmatischen Presetfokus erhalten ' + JSON.stringify(after));
        assert(after.visible, label + ': Feld, Zeile, Details und Vorfahren bleiben nach Timerabschluss sichtbar');
        assert(JSON.stringify(await readBrowserDynamicRecords(page)) === JSON.stringify(before), label + ': gesamte Rohstrings und Belege bytegleich');
        smoke.assertNoErrors();
    } finally { await smoke.close(); }
}
async function runDynamicFlexErrorCorrectionSmoke(browser, baseUrl, annual) {
    await runDynamicFlexVisibleDetailBlurSmoke(browser, baseUrl, annual);
    for (const target of ['off', 'konservativ']) for (const direction of ['Tab', 'Shift+Tab']) {
        const { records } = browserDynamicRecords('active', annual);
        const smoke = annual
            ? await openSmokePage(browser, baseUrl, 'index.html', { storage: records, fixedTime: '2027-01-02T12:00:00+01:00', annualFixtures: { targetYear: 2026 }, observeWealthUpdates: true })
            : await createPage(browser, 'Managerfehlerkorrektur ' + target, { storage: records, fixedTime: '2026-10-09T12:00:00Z' });
        const { page } = smoke;
        try {
            let root;
            if (annual) {
                await page.locator('[data-overview-annual]').waitFor(); await waitForWealthBrowserIdle(page);
                await page.locator('[data-overview-annual]').click();
                await prepareBrowserClose(page);
                await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
                const dialog = page.locator('#balanceAnnualClose');
                await dialog.locator('[data-close-dialog-activate="preview"]').click();
                await dialog.locator('[data-annual-plan-toggle]').click();
                root = dialog.locator('[data-annual-plan-editor]');
            } else {
                await page.goto(`${baseUrl}/depot-tranchen-manager.html#haushalt-plan`);
                await waitForPageCondition(page, () => document.getElementById('managerPlan_dynamicFlex')?.disabled === false);
                await waitForPageCondition(page, key => ['complete', 'empty'].includes(JSON.parse(sessionStorage.getItem(key) || 'null')?.status), STARTUP_PRICE_SESSION_KEY);
                root = page.locator('#managerHouseholdPlan');
            }
            const prefix = annual ? 'annualPlan_' : 'managerPlan_', fieldId = prefix + 'goGoMultiplier';
            const field = root.locator('#' + fieldId), label = (annual ? 'Jahreseditor' : 'Manager') + '/' + target + '/' + direction;
            await root.locator('[data-plan-dynamic-preset="custom"]').click();
            const before = await readBrowserDynamicRecords(page);
            await page.evaluate(async () => {
                const { PersistenceFacade: p } = await import('./app/shared/persistence-facade.js');
                const replace = p.replaceRecordsTransactional;
                window.__dynamicErrorPlanWrites = [];
                p.replaceRecordsTransactional = function(records, ...args) {
                    if (Object.hasOwn(records, 'household_plan_v1')) window.__dynamicErrorPlanWrites.push(records.household_plan_v1);
                    return replace.call(this, records, ...args);
                };
            });
            await field.fill('unlesbar');
            for (const key of ['off', 'konservativ', 'ausgewogen', 'offensiv', 'custom', target]) {
                // Echtes click löst change/blur vor Segmentfokus aus.
                await root.locator('[data-plan-dynamic-preset="' + key + '"]').click();
                await assertBrowserDynamicError(page, root, fieldId, label + '/' + key);
                if (annual) assert(await page.locator('#annualConfirmBtn').isDisabled(), label + ': Jahresbestätigung gesperrt');
                else assert(await page.evaluate(async () => (await import('./app/tranches/tranchen-manager-page.js')).flushManagerHouseholdPlan()) === false, label + ': Flush bestätigt keinen ungültigen Batch');
                assert(JSON.stringify(await readBrowserDynamicRecords(page)) === JSON.stringify(before), label + ': alle Backend-, Cache- und lokalen Rohstrings bytegleich');
                assert(await page.evaluate(() => window.__dynamicErrorPlanWrites.length) === 0, label + ': keine isolierten Presetwrites');
            }
            if (!annual) {
                await page.waitForTimeout(400);
                assert(JSON.stringify(await readBrowserDynamicRecords(page)) === JSON.stringify(before), label + ': Autosavefenster ohne Write');
            }
            assert(!await root.locator('#' + prefix + 'goGoActive').isChecked(), label + ': Go-Go bleibt aus');
            await field.focus(); await page.keyboard.press('ControlOrMeta+A');
            for (const [character, text] of [['1', '1'], [',', '1,'], ['1', '1,1'], ['7', '1,17']]) {
                await page.keyboard.type(character);
                if (!annual && text === '1') await page.waitForTimeout(400);
                assert(await field.inputValue() === text, label + ': exakter Text nach Zeichen ' + text);
                assert(await field.evaluate(node => node === document.activeElement), label + ': unveränderter Dokumentfokus bei ' + text);
                assert(await field.evaluate(node => {
                    const root = node.closest('[data-annual-plan-editor], #managerHouseholdPlan');
                    for (; node; node = node.parentElement) {
                        if (node.hidden) return false;
                        if (node === root) return true;
                    }
                    return false;
                }) && await field.isVisible(), label + ': Feld, Zeile, Details und Vorfahren bis Wurzel sichtbar bei ' + text);
                if (text === '1,') {
                    assert(await field.getAttribute('aria-invalid') === 'true', label + ': unvollständige Zahl ungültig');
                    if (annual) assert(await page.locator('#annualConfirmBtn').isDisabled(), label + ': unvollständige Zahl sperrt Jahresbestätigung');
                }
                assert(await page.evaluate(() => window.__dynamicErrorPlanWrites.length) === 0, label + ': kein Zwischenwrite bei ' + text);
                assert(JSON.stringify(await readBrowserDynamicRecords(page)) === JSON.stringify(before), label + ': gesamte Rohstrings während Korrektur unverändert');
            }
            assert(await field.getAttribute('aria-invalid') === 'false' && await root.locator('#' + fieldId + '_error').isHidden(), label + ': direkte Korrektur entfernt Feldmeldung');
            assert(!await root.locator('#' + prefix + 'goGoActive').isChecked(), label + ': Korrektur aktiviert Go-Go nicht');
            if (annual) {
                await prepareBrowserClose(page);
                await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
                assert(JSON.stringify(await readBrowserDynamicRecords(page)) === JSON.stringify(before), label + ': gültige Korrekturvorschau bleibt schreibfrei');
            }
            // Nativer Tastaturschritt: sein internes Ziel kann beim Blur verschwinden.
            await page.keyboard.press(direction);
            await waitForPageCondition(page, ({ annual, target }) => {
                const root = document.querySelector(annual ? '[data-annual-plan-editor]' : '#managerHouseholdPlan');
                const active = document.activeElement, details = root?.querySelector('[data-plan-dynamic-details]');
                if (!active || active === document.body || active.disabled || !root?.contains(active) || !active.getClientRects().length) return false;
                if (annual && (!document.getElementById('balanceAnnualClose')?.open || !document.getElementById('balanceAnnualClose').contains(active))) return false;
                if (details.hidden !== (target === 'off')) return false;
                for (let node = active; node; node = node.parentElement) {
                    if (node.hidden || node.inert) return false;
                    if (node === root) return true;
                }
                return false;
            }, { annual, target });
            assert(await root.evaluate(root => {
                const active = document.activeElement;
                if (active === document.body || active.disabled || !root.contains(active) || !active.getClientRects().length) return false;
                for (let node = active; node; node = node.parentElement) {
                    if (node.hidden || node.inert) return false;
                    if (node === root) return true;
                }
                return false;
            }), label + ': tatsächlicher Endfokus sichtbar und aktiviert innerhalb der Editorwurzel');
            if (annual) assert(await page.locator('#balanceAnnualClose').evaluate(dialog => dialog.open && dialog.contains(document.activeElement)), label + ': Endfokus im offenen Jahresdialog');
            assert(await field.evaluate(node => node !== document.activeElement && node.parentElement.hidden), label + ': Faktorzeile nach Blur wieder verborgen');
            assert(await root.locator('[data-plan-dynamic-details]').isHidden() === (target === 'off'), label + ': reguläre Detailerkennung nach Blur');
            if (!annual) {
                await waitForPageCondition(page, async () => {
                    const { PersistenceFacade: p } = await import('./app/shared/persistence-facade.js');
                    const records = await p.readPersistedRecords();
                    return Object.values(JSON.parse(records.household_plan_v1).entries).find(entry => entry.scope.kind === 'household').values.goGoMultiplier === 1.17;
                });
                assert(await page.evaluate(async () => (await import('./app/tranches/tranchen-manager-page.js')).flushManagerHouseholdPlan()) === true, label + ': gültiger Batch bestätigt');
                const committed = await readBrowserDynamicPlan(page);
                assert(committed.values.goGoMultiplier === 1.17 && committed.values.goGoActive === false
                    && Object.entries({ ...browserDynamicValues[target], goGoMultiplier: 1.17 }).every(([path, value]) => Object.is(committed.values[path], value)), label + ': Backend bestätigt vollständigen korrigierten Zielpresetbatch');
                assert(await page.evaluate(expected => window.__dynamicErrorPlanWrites.every(raw => {
                    const values = Object.values(JSON.parse(raw).entries).find(entry => entry.scope.kind === 'household').values;
                    return Object.entries(expected).every(([path, value]) => Object.is(values[path], value));
                }), { ...browserDynamicValues[target], goGoMultiplier: 1.17 }), label + ': alle Writerohstrings enthalten ausschließlich den vollständigen Endbatch');
                assert(await page.evaluate(() => window.__dynamicErrorPlanWrites.length) === 1, label + ': genau ein bestätigter Planwrite');
            }
            await root.locator('[data-plan-dynamic-preset="custom"]').click();
            assert(await field.inputValue() === '1,17', label + ': Custom erhält korrigierten Wert');
            if (annual) {
                await root.locator('[data-annual-plan-discard]').click();
                await prepareBrowserClose(page);
                await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
                assert(await field.getAttribute('aria-invalid') === 'false' && await root.locator('#' + fieldId + '_error').isHidden(), label + ': Verwerfen stellt gültige Basis wieder her');
                assert(JSON.stringify(await readBrowserDynamicRecords(page)) === JSON.stringify(before), label + ': Verwerfen ohne Fachwrite');
            } else assert(await page.evaluate(async () => (await import('./app/tranches/tranchen-manager-page.js')).flushManagerHouseholdPlan()) === true, label + ': Custombatch bestätigt');
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}
async function runDynamicFlexCrosspageSmoke(browser, baseUrl) {
    await runDynamicFlexErrorCorrectionSmoke(browser, baseUrl, false);
    for (const matching of [false, true, 'active']) {
        const { records, original } = browserDynamicRecords(matching);
        const expected = matching === true ? 'ausgewogen' : 'custom';
        const smoke = await createPage(browser, 'Dynamic Flex Voreinstellungen seitenübergreifend ' + expected, { storage: records, fixedTime: '2026-10-09T12:00:00Z' });
        const { page } = smoke;
        try {
            await page.goto(`${baseUrl}/depot-tranchen-manager.html#haushalt-plan`);
            await waitForPageCondition(page, () => document.getElementById('managerPlan_dynamicFlex')?.disabled === false);
            await waitForPageCondition(page, key => ['complete', 'empty'].includes(JSON.parse(sessionStorage.getItem(key) || 'null')?.status), STARTUP_PRICE_SESSION_KEY);
            const root = page.locator('#managerHouseholdPlan');
            if (matching === 'active') {
                const before = await readBrowserDynamicPlan(page);
                await assertBrowserDynamicTyping(page, root, 'managerPlan_goGoMultiplier', 'Manager');
                await waitForPageCondition(page, async () => {
                    const records = await (await import('./app/shared/persistence-facade.js')).PersistenceFacade.readPersistedRecords();
                    return Object.values(JSON.parse(records.household_plan_v1).entries).some(entry => entry.values.goGoMultiplier === 1.15);
                });
                const committed = await readBrowserDynamicPlan(page);
                assert(JSON.stringify(committed.values) === JSON.stringify({ ...original, goGoMultiplier: 1.15 }), 'Managerautosave bestätigt vollständig getippten Faktor 1,15');
                assert(committed.receipt === before.receipt, 'Faktoreingabe erzeugt keinen Jahresbeleg');
                assert(await root.locator('[data-plan-dynamic-details]').isVisible(), 'Details nach Faktorenautosave offen');
                assert(await root.locator('#managerPlan_goGoMultiplier').evaluate(node => node === document.activeElement), 'Autosave erhält Faktor-Fokus');
                // DOM-Klick lässt den Fokus bis zum produktiven Schließpfad im Feld.
                await root.locator('[data-plan-dynamic-preset="ausgewogen"]').evaluate(node => node.click());
                assert(await root.locator('[data-plan-dynamic-details]').isHidden(), 'Bewusste Managerpresetwahl schließt');
                assert(await root.locator('[data-plan-dynamic-details]').evaluate(node => !node.contains(document.activeElement)), 'Managerfokus liegt nach Schließen außerhalb der Details');
                smoke.assertNoErrors(); continue;
            }
            assert(await root.locator('[data-plan-dynamic-preset="off"]').getAttribute('aria-pressed') === 'true', 'Manager erkennt Aus trotz alter Details');
            assert(await root.locator('[data-plan-dynamic-details]').isHidden(), 'Aus verbirgt Details');
            const before = await readBrowserDynamicPlan(page);
            // Fehler an der realen Transaktionsgrenze, danach sichtbarer Retry.
            if (!matching) await page.evaluate(async () => {
                const { PersistenceFacade: p } = await import('./app/shared/persistence-facade.js');
                const original = p.replaceRecordsTransactional;
                p.replaceRecordsTransactional = async function(records, ...args) {
                    if (Object.hasOwn(records, 'household_plan_v1')) { p.replaceRecordsTransactional = original; throw new Error('Synthetischer Preset-Speicherfehler'); }
                    return original.call(this, records, ...args);
                };
            });
            if (!matching) {
                await root.locator('#managerPlan_minimumFlexAnnual').fill('999999');
                await root.locator('[data-plan-dynamic-preset="custom"]').click();
                await root.locator('#managerPlanStatus').filter({ hasText: 'Mindest-Flex' }).waitFor();
                await page.waitForTimeout(400); // Autosavefenster ohne gültigen Batch überschreiten.
                assert((await readBrowserDynamicPlan(page)).raw === before.raw, 'Ungültiger Managertext verhindert isolierte Aktivierung');
                assert(await root.locator('#managerPlan_minimumFlexAnnual').inputValue() === '999999', 'Managercustom verwirft ungültige Eingabe nicht');
                await root.locator('#managerPlan_minimumFlexAnnual').fill(String(original.minimumFlexAnnual));
            }
            await root.locator('[data-plan-dynamic-preset="custom"]').click();
            assert(await root.locator('[data-plan-dynamic-details]').isVisible(), 'Aus → Custom öffnet echte Details');
            if (!matching) {
                await root.locator('#managerPlanRetry').waitFor({ state: 'visible' });
                assert((await readBrowserDynamicPlan(page)).raw === before.raw, 'Fehler persistiert keinen isolierten Einschaltwert');
                await root.locator('#managerPlanRetry').click();
            }
            await waitForPageCondition(page, async () => Object.values(JSON.parse((await (await import('./app/shared/persistence-facade.js')).PersistenceFacade.readPersistedRecords()).household_plan_v1).entries).some(entry => entry.values.dynamicFlex === true));
            const committed = await readBrowserDynamicPlan(page);
            assert(JSON.stringify(committed.values) === JSON.stringify({ ...original, dynamicFlex: true }), 'Managerautosave erhält sämtliche Detailwerte');
            assert(committed.receipt === before.receipt, 'Manager schreibt keinen Abschlussbeleg');
            assert(await root.locator('[data-plan-dynamic-preset="custom"]').getAttribute('aria-pressed') === 'true', 'Öffnungsabsicht überlebt Autosave');
            await assertBrowserDynamicDetails(page, root, 'manager-' + expected);
            await page.reload(); await waitForPageCondition(page, () => document.getElementById('managerPlan_dynamicFlex')?.disabled === false);
            assert(await root.locator('[data-plan-dynamic-preset="' + expected + '"]').getAttribute('aria-pressed') === 'true', 'Reload erkennt aktives Preset oder Custom, niemals Aus');
            assert(JSON.stringify((await readBrowserDynamicPlan(page)).values) === JSON.stringify(committed.values), 'Reload erhält dynamische Details bytegleich');
            await page.goto(`${baseUrl}/Balance.html`);
            await waitForHouseholdPlanStart(page);
            await waitBalanceHouseholdList(page);
            await page.locator('#balanceTabStrategy').click();
            await waitForPageCondition(page, key => document.querySelector('#dynamicFlexPreset-segments [data-balance-value="' + key + '"]')?.getAttribute('aria-pressed') === 'true', expected);
            await page.locator('#dynamicFlexPreset-segments [data-balance-value="custom"]').click();
            assert(await page.locator('#balanceAllParameters').evaluate(node => node.open), 'Balance öffnet Custom über sichtbares Segment');
            assert((await readBrowserDynamicPlan(page)).raw === committed.raw, 'Balanceöffnung schreibt keinen Plan');
            await page.goto(`${baseUrl}/Simulator.html`); await waitForSimulatorOpening(page, 'Simulator.html');
            await openSimulatorTab(page, 'annahmen');
            const strategyToggle = page.locator('[data-assumption-step="3"] [data-step-toggle]');
            if (await strategyToggle.getAttribute('aria-expanded') === 'false') await strategyToggle.click();
            await waitForPageCondition(page, key => document.getElementById('dynamicFlexPreset')?.value === key, expected);
            assert(await page.locator('#dynamicFlexPreset').isDisabled(), 'Simulatorlesemodus hält Presets gesperrt');
            await openSimulatorPlanTrial(page);
            await page.locator('#dynamicFlexPreset').selectOption('offensiv');
            assert((await readBrowserDynamicPlan(page)).raw === committed.raw, 'Simulatorpreset bleibt im Versuch');
            await page.locator('#simPlanTrialBack').click();
            await waitForPageCondition(page, key => document.getElementById('dynamicFlexPreset')?.value === key, expected);
            assert((await readBrowserDynamicPlan(page)).raw === committed.raw, 'Zurück zum Plan erhält bestätigte Planbytes');
            // Alle Wertpresets vollständig über sichtbare Managersegmente prüfen.
            await page.goto(`${baseUrl}/depot-tranchen-manager.html#haushalt-plan`);
            await waitForPageCondition(page, () => document.getElementById('managerPlan_dynamicFlex')?.disabled === false);
            for (const [key, values] of Object.entries(browserDynamicValues)) {
                await root.locator('[data-plan-dynamic-preset="' + key + '"]').click();
                await waitForPageCondition(page, async ({ key, values }) => {
                    const records = await (await import('./app/shared/persistence-facade.js')).PersistenceFacade.readPersistedRecords();
                    const plan = Object.values(JSON.parse(records.household_plan_v1).entries).find(entry => entry.scope.kind === 'household').values;
                    return Object.entries(values).every(([path, value]) => Object.is(plan[path], value)) && document.querySelector('[data-plan-dynamic-preset="' + key + '"]')?.getAttribute('aria-pressed') === 'true';
                }, { key, values });
                const current = await readBrowserDynamicPlan(page);
                assert(JSON.stringify(current.values) === JSON.stringify({ ...committed.values, ...values }), 'Vollständiges Preset, unveränderte übrige Felder und CAPE: ' + key);
                assert(await root.locator('[data-plan-dynamic-details]').isHidden() && await root.locator('[data-plan-dynamic-hint]').isVisible(), key + ': Details verborgen, Hinweis sichtbar');
            }
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}
async function runDynamicFlexAnnualSmoke(browser, baseUrl) {
    await runDynamicFlexErrorCorrectionSmoke(browser, baseUrl, true);
    for (const matching of [false, true, 'active']) {
        const { records, original } = browserDynamicRecords(matching, true), expected = matching === true ? 'ausgewogen' : 'custom';
        const smoke = await openSmokePage(browser, baseUrl, 'index.html', { storage: records,
            fixedTime: '2027-01-02T12:00:00+01:00', annualFixtures: { targetYear: 2026 }, observeWealthUpdates: true });
        const { page } = smoke;
        try {
            await page.locator('[data-overview-annual]').waitFor(); await waitForWealthBrowserIdle(page);
            const before = await readBrowserDynamicPlan(page);
            const open = async () => {
                await page.locator('[data-overview-annual]').click();
                await prepareBrowserClose(page);
                await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
                const root = page.locator('#balanceAnnualClose');
                await root.locator('[data-close-dialog-activate="preview"]').click();
                await root.locator('[data-annual-plan-toggle]').click(); return root;
            };
            let root = await open();
            if (matching === 'active') {
                await assertBrowserDynamicTyping(page, root, 'annualPlan_goGoMultiplier', 'Jahreseditor');
                await prepareBrowserClose(page);
                await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
                assert(await root.locator('#annualPlan_goGoMultiplier').inputValue() === '1,15', 'Aktuelle Jahresvorschau erhält Faktor 1,15');
                assert(await root.locator('[data-plan-dynamic-details]').isVisible()
                    && await root.locator('#annualPlan_goGoMultiplier').evaluate(node => node === document.activeElement), 'Jahresvorschau erhält Details und Faktor-Fokus');
                assert(JSON.stringify(await readBrowserDynamicPlan(page)) === JSON.stringify(before), 'Tippen und Vorschau schreiben weder Plan noch Jahresbeleg');
                await root.locator('[data-plan-dynamic-preset="ausgewogen"]').evaluate(node => node.click());
                assert(await root.locator('[data-plan-dynamic-details]').isHidden(), 'Bewusste Jahrespresetwahl schließt trotz synchroner Rückmeldung');
                assert(await root.locator('[data-plan-dynamic-details]').evaluate(node => !node.contains(document.activeElement)), 'Jahresfokus liegt nach Schließen außerhalb der Details');
                await prepareBrowserClose(page);
                await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
                assert(JSON.stringify(await readBrowserDynamicPlan(page)) === JSON.stringify(before), 'Ausdrückliche Presetwahl bleibt Entwurf ohne Persistenz');
                smoke.assertNoErrors(); continue;
            }
            assert(await root.locator('[data-plan-dynamic-preset="off"]').getAttribute('aria-pressed') === 'true', 'Abschluss erkennt ausgeschaltete alte Details');
            const recommendation = JSON.stringify(await root.locator('[data-annual-recommendation]').allTextContents());
            await root.locator('[data-plan-dynamic-preset="custom"]').click();
            await prepareBrowserClose(page);
            await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
            assert(await page.locator('#annualPlan_dynamicFlex').isChecked(), 'Abschlussentwurf enthält Einschalten');
            assert(await root.locator('[data-plan-dynamic-details]').isVisible(), 'Abschlusscustom öffnet Details auch bei presetgleichen Werten');
            assert(JSON.stringify(await readBrowserDynamicPlan(page)) === JSON.stringify(before), 'Abschlussentwurf persistiert weder Plan noch Beleg');
            await assertBrowserDynamicDetails(page, root, 'abschluss-' + expected);
            await root.locator('[data-annual-plan-discard]').click();
            await prepareBrowserClose(page);
            await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
            assert(!await page.locator('#annualPlan_dynamicFlex').isChecked(), 'Verwerfen erhält ausgeschaltete Empfehlung');
            assert(JSON.stringify(await readBrowserDynamicPlan(page)) === JSON.stringify(before), 'Verwerfen erhält Plan und Beleg');
            await root.locator('[data-plan-dynamic-preset="custom"]').click();
            await prepareBrowserClose(page);
            await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
            await root.getByRole('button', { name: 'Schließen', exact: true }).click(); await root.waitFor({ state: 'hidden' });
            assert(JSON.stringify(await readBrowserDynamicPlan(page)) === JSON.stringify(before), 'Abbruch speichert kein Einschalten');
            root = await open();
            await page.locator('#annualPlan_minimumFlexAnnual').fill('999999');
            await root.locator('[data-plan-dynamic-preset="custom"]').click();
            assert(await page.locator('#annualConfirmBtn').isDisabled(), 'Ungültiger vorhandener Text verhindert Einschaltbestätigung');
            assert(await page.locator('#annualPlan_minimumFlexAnnual').inputValue() === '999999', 'Abschlusscustom verwirft ungültigen Text nicht');
            assert(JSON.stringify(await readBrowserDynamicPlan(page)) === JSON.stringify(before), 'Ungültiger Entwurf schreibt keine Aktivierung');
            await root.locator('[data-annual-plan-discard]').click();
            await prepareBrowserClose(page);
            await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
            await root.locator('[data-plan-dynamic-preset="custom"]').click();
            await prepareBrowserClose(page);
            await waitForPageCondition(page, () => document.getElementById('annualConfirmBtn')?.disabled === false);
            assert(JSON.stringify(await root.locator('[data-annual-recommendation]').allTextContents()) === recommendation, 'Presetentwurf erhält Empfehlung');
            await prepareBrowserClose(page);
            await page.locator('#annualConfirmBtn').click();
            await waitForPageCondition(page, () => document.getElementById('balanceAnnualClose')?.dataset.annualYearResult === 'confirmed');
            const adopted = await readBrowserDynamicPlan(page);
            assert(adopted.values.dynamicFlex === true && adopted.receipt !== before.receipt, 'Erst Jahresbestätigung übernimmt Aktivierung und Beleg');
            for (const path of Object.keys(browserDynamicValues.ausgewogen).filter(path => path !== 'dynamicFlex')) assert(Object.is(adopted.values[path], original[path]), 'Jahresbestätigung bewahrt Detailwert ' + path);
            await page.keyboard.press('Escape'); await root.waitFor({ state: 'hidden' });
            await page.goto(`${baseUrl}/depot-tranchen-manager.html#haushalt-plan`);
            await waitForPageCondition(page, () => document.getElementById('managerPlan_dynamicFlex')?.disabled === false);
            assert(await page.locator('[data-plan-dynamic-preset="' + expected + '"]').getAttribute('aria-pressed') === 'true', 'Neues Lesen nach Abschluss erkennt aktives Preset oder Custom');
            assert((await readBrowserDynamicPlan(page)).raw === adopted.raw, 'Neulesen ändert beschlossenen Plan nicht');
            smoke.assertNoErrors();
        } finally { await smoke.close(); }
    }
}

